package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Assigns the owner's {@code householdSize} on create: the number of owners sharing the same
 * {@code householdId} once this owner is counted. Runs after {@link AssignHousehold} (which sets
 * the {@code householdId} on this owner and back-fills existing household members), so the shared
 * identifier is in place before the count.
 *
 * <p>The new owner is not yet saved, so it is counted by adding one to the existing same-household
 * members. An owner with no {@code householdId} (did not opt into a shared household) is a
 * household of one.
 */
public class CountHouseholdMembers {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String householdId = owner.getHouseholdId();
        if (householdId == null) {
            owner.setHouseholdSize(1);
            return;
        }
        int existing = (int) ownerRepository.findAll().stream()
                .filter(existingOwner -> existingOwner.getId() == null
                        || !existingOwner.getId().equals(owner.getId()))
                .filter(existingOwner -> householdId.equals(existingOwner.getHouseholdId()))
                .count();
        owner.setHouseholdSize(existing + 1);
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Single source of truth for an owner's {@code identityKey} — the one derived value that all
 * duplicate detection is now expressed through. The key is
 * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}, so two owners are
 * duplicates only when their WHOLE keys match: two members of the same household (same
 * {@code householdId}) with different telephones have different keys and are both allowed.
 *
 * <p>The three parts are normalized the same way they are stored: the telephone to its E.164
 * form (see {@link OwnerTelephones}, so a stored value that predates the pipeline still
 * compares correctly), the email trimmed and lower-cased (empty when absent), and the
 * {@code householdId} as stored (empty when absent). Used by {@link RejectDuplicateIdentity}
 * to find collisions and by the owner mapper to return the key.
 */
public final class OwnerIdentity {

    private OwnerIdentity() {
    }

    /** The owner's duplicate-detection identity key. */
    public static String identityKey(Owner owner) {
        String telephone = OwnerTelephones.toE164(owner.getTelephone());
        if (telephone == null) {
            telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
        }
        String email = owner.getEmail();
        email = (email == null || email.isBlank()) ? "" : email.trim().toLowerCase(Locale.ROOT);
        String household = owner.getHouseholdId();
        household = household == null ? "" : household;
        return telephone + "|" + email + "|" + household;
    }
}

package org.springframework.samples.petclinic.rest.escalation;

/**
 * Thrown by the create pipeline when a new owner's whole {@code identityKey}
 * ({@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}) equals an
 * existing owner's. This single key consolidates the former separate telephone, email and
 * household duplicate checks. Handled globally by {@link DuplicateIdentityExceptionHandler},
 * which responds 409.
 */
public class DuplicateIdentityException extends Exception {

    public DuplicateIdentityException(String message) {
        super(message);
    }
}

